export class Flat3DIndex {
    _getIndex;
    _getXYZ;
    position;
    bounds;
    constructor(_getIndex, _getXYZ) {
        this._getIndex = _getIndex;
        this._getXYZ = _getXYZ;
        this.position = [0, 0, 0];
        this.bounds = [1, 1, 1];
    }
    static GetXZYOrder() {
        return new Flat3DIndex((position, bounds) => position[0] +
            position[2] * bounds[0] +
            position[1] * bounds[0] * bounds[2], (index, bounds, position) => {
            position[1] = Math.floor(index / (bounds[0] * bounds[2]));
            position[2] = Math.floor((index % (bounds[0] * bounds[2])) / bounds[0]);
            position[0] = Math.floor(index % bounds[0]);
        });
    }
    static GetXYZOrder() {
        return new Flat3DIndex((position, bounds) => position[0] +
            position[1] * bounds[0] +
            position[2] * bounds[0] * bounds[1], (index, bounds, position) => {
            position[2] = Math.floor(index / (bounds[0] * bounds[1]));
            position[1] = Math.floor((index % (bounds[0] * bounds[1])) / bounds[0]);
            position[0] = Math.floor(index % bounds[0]);
        });
    }
    static GetYXZOrder() {
        return new Flat3DIndex((position, bounds) => position[1] + bounds[1] * (position[0] + bounds[0] * position[2]), (index, bounds, position) => {
            position[2] = Math.floor(index / (bounds[0] * bounds[1]));
            position[0] = Math.floor((index % (bounds[0] * bounds[1])) / bounds[1]);
            position[1] = index % bounds[1];
        });
    }
    get size() {
        return this.bounds[0] * this.bounds[1] * this.bounds[2];
    }
    getIndex(position) {
        return this._getIndex(position, this.bounds);
    }
    getIndexVec3Array(position) {
        this.position[0] = position[0];
        this.position[1] = position[1];
        this.position[2] = position[2];
        return this._getIndex(this.position, this.bounds);
    }
    getIndexXYZ(x, y, z) {
        this.position[0] = x;
        this.position[1] = y;
        this.position[2] = z;
        return this._getIndex(this.position, this.bounds);
    }
    getIndexVec3(position) {
        this.position[0] = position.x;
        this.position[1] = position.y;
        this.position[2] = position.z;
        return this._getIndex(this.position, this.bounds);
    }
    output = [0, 0, 0];
    getXYZ(index) {
        this._getXYZ(index, this.bounds, this.output);
        return this.output;
    }
    getBounds() {
        return this.bounds;
    }
    setBounds(x, y, z) {
        this.bounds[0] = x;
        this.bounds[1] = y;
        this.bounds[2] = z;
    }
}
